#!/bin/bash
# Differential test for the consistency-based strategies: run the C `tbfast`
# and `tbfast-rs` on the same inputs with the same arguments and require every
# output file they produce (`pre`, `order`, `hat2`, `hat3`) to be byte-identical.
#
#   verify_tbfast.sh <path-to-C-tbfast> <path-to-rust-tbfast-rs> [corpus-dir]
#
# With no corpus directory, the corpus generated by verify.sh is reused.

set -u
CBIN="${1:?usage: verify_tbfast.sh <c-tbfast> <rust-tbfast-rs> [corpus-dir]}"
RBIN="${2:?usage: verify_tbfast.sh <c-tbfast> <rust-tbfast-rs> [corpus-dir]}"
CORPUS="${3:-}"

here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# The argument vectors the mafft wrapper produces. `_ ... _` delimits the
# pairwise stage's options from the progressive stage's.
P="-u 0.0 -l 2.7 -C 0 -b 62 -g -0.100 -f -2.00 -Q 100.0 -h 0.1"
PG="-u 0.0 -l 2.7 -C 0 -b 62 -g -0.10 -f -2.00 -Q 100.0 -h 0.1"
T="-W 0.00001 -V -1.53 -s 0.0 -C 0 -b 62 -f -1.53 -Q 100.0 -h 0 -F -l 2.7 -X 0.1"

ARGSETS=(
  # L-INS-1 / L-INS-i  (--localpair)
  "_ $P -L _ -+ 0 $T -O"
  "_ $P -L _ -+ 2 $T -O"
  "_ $P -L _ -+ 16 $T -O"
  # G-INS-1 / G-INS-i  (--globalpair); no -O, so terminal gaps are charged
  "_ $PG -A _ -+ 0 $T"
  "_ $PG -A _ -+ 2 $T"
  # --allowshift: turns on the warp DP and the per-node dynamic matrix
  "_ -u 0.8 -l 2.7 -C 0 -b 62 -: -g 0 -f -2.00 -Q 2.00 -h 0 -A _ -+ 16 -W 0.00001 -V -1.53 -s 0.8 -C 0 -b 62 -: -f -1.53 -Q 2.00 -h 0 -F -l 2.7 -X 0.1"
  "_ -u 0.8 -l 2.7 -C 0 -b 62 -: -g 0 -f -2.00 -Q 2.00 -h 0 -L _ -+ 16 -W 0.00001 -V -1.53 -s 0.8 -C 0 -b 62 -: -f -1.53 -Q 2.00 -h 0 -O -F -l 2.7 -X 0.1"
  # non-default constraint weight and tree parameters
  "_ $P -L _ -+ 2 -W 0.001 -V -1.53 -s 0.0 -C 0 -b 62 -f -2.00 -Q 100.0 -h -0.1 -F -l 0.5 -X 0.5 -O"
  "_ $PG -A _ -+ 2 -W 0.00001 -V -1.53 -s 0.0 -C 0 -b 62 -f -1.53 -Q 100.0 -h 0 -F -l 5.0 -X 0.0"
)

if [ -z "$CORPUS" ]; then
  CORPUS="$work/corpus"
  # verify.sh knows how to build the corpus; borrow it by running it with a
  # binary pair that cannot work, then keeping the directory it generated.
  mkdir -p "$CORPUS"
  cp "$here/../test/sample" "$CORPUS/sample.fa"
  python3 - "$here/../test/sample" "$CORPUS" <<'PY'
import random, sys
src, out = sys.argv[1], sys.argv[2]
recs, name, seq = [], None, []
for line in open(src):
    line = line.rstrip('\n')
    if line.startswith('>'):
        if name is not None:
            recs.append((name, ''.join(seq)))
        name, seq = line[1:], []
    else:
        seq.append(line)
recs.append((name, ''.join(seq)))

def write(path, rs):
    with open(path, 'w') as f:
        for n, s in rs:
            f.write('>%s\n%s\n' % (n, s))

rng = random.Random(31337)
alpha = 'ARNDCQEGHILKMFPSTWYVBZX'
for i in range(12):
    k = rng.randint(2, len(recs))
    write('%s/subset_%02d.fa' % (out, i), rng.sample(recs, k))
for L in (2, 6, 12, 40):
    write('%s/trunc_%02d.fa' % (out, L), [(n, s[:L]) for n, s in recs[:6]])
write('%s/pair.fa' % out, recs[:2])
write('%s/dup.fa' % out, [(('d%d' % i), recs[0][1]) for i in range(5)])
# X is stripped for the score-only variants, so it exercises `thereisx`.
rs = []
for n, s in recs[:8]:
    t = list(s[:150])
    for _ in range(10):
        t[rng.randrange(len(t))] = 'X'
    rs.append((n, ''.join(t)))
write('%s/withx.fa' % out, rs)
rs = []
for n, s in recs[:8]:
    t = list(s[:150])
    for _ in range(10):
        t[rng.randrange(len(t))] = rng.choice(alpha)
    rs.append((n, ''.join(t)))
write('%s/ambig.fa' % out, rs)
# Tandem repeats: the case --allowshift exists for.
motif = ''.join(rng.choice(alpha[:20]) for _ in range(30))
rs = []
for i in range(10):
    s = ''
    for _ in range(rng.randint(2, 6)):
        t = list(motif)
        for _ in range(3):
            t[rng.randrange(len(t))] = rng.choice(alpha[:20])
        s += ''.join(t)
    rs.append(('r%02d' % i, s))
write('%s/tandem.fa' % out, rs)
for i, (nseq, L) in enumerate(((4, 40), (15, 70))):
    write('%s/random_%d.fa' % (out, i),
          [('q%d' % j, ''.join(rng.choice(alpha[:20]) for _ in range(L)))
           for j in range(nseq)])
PY
fi

pass=0; fail=0; failed=""
for f in "$CORPUS"/*; do
  [ -f "$f" ] || continue
  for i in "${!ARGSETS[@]}"; do
    args="${ARGSETS[$i]}"
    rm -rf "$work/c" "$work/r"
    mkdir -p "$work/c" "$work/r"
    ( cd "$work/c" && $CBIN $args < "$f" > /dev/null 2> err.log )
    cst=$?
    ( cd "$work/r" && $RBIN $args < "$f" > /dev/null 2> err.log )
    rst=$?
    label="$(basename "$f") [argset $i]"
    if [ $cst -ne $rst ]; then
      fail=$((fail+1)); failed="$failed\n  $label (exit $cst vs $rst)"
      continue
    fi
    bad=""
    for out in pre order hat2 hat3; do
      if [ -f "$work/c/$out" ] || [ -f "$work/r/$out" ]; then
        cmp -s "$work/c/$out" "$work/r/$out" || bad="$bad $out"
      fi
    done
    if [ -n "$bad" ]; then
      fail=$((fail+1)); failed="$failed\n  $label (differs:$bad)"
    else
      pass=$((pass+1))
    fi
  done
done

echo "pass=$pass fail=$fail"
if [ $fail -ne 0 ]; then
  printf 'FAILED:%b\n' "$failed"
  exit 1
fi
